    assert(i < binfo->ngroups);
#endif

    // Atomically set the bit
    size_t goff = bit >> LG_BITMAP_GROUP_NBITS;
    bitmap_t *gp = &bitmap[goff];
    bitmap_t g = *gp;
    bitmap_t mask = ZU(1) << (bit & BITMAP_GROUP_NBITS_MASK);
    while (true) {
        if ((g & mask) != 0) {
