        g = atomic_exchange_u(&gp->bits, g | mask, ATOMIC_ACQ_REL);
        if (g == old_g) {
            break;
        }
        // CAS failed, retry
    }

    // Propagate the change up the tree if needed
#ifdef BITMAP_USE_TREE
    if ((g & ~mask) == 0) {
        unsigned level;
