            g = *gp;
            mask = ZU(1) << (bit & BITMAP_GROUP_NBITS_MASK);
            if ((g & mask) == 0) {
                break;
            }
            atomic_store_u(&gp->bits, g & ~mask, ATOMIC_RELEASE);
            if ((g & ~mask) != 0) {
                break;
            }
        }
    }
#endif

    return bit;

